dir:



































































&DefaultButton;




function dir$dmvb(p){
  this.constructor(p);
}
dir$dmvb.prototype = new DirEvent();
dir$dmvb.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmvb.prototype.afterInit = function(renderType){
    var p = this._dir,g = p.options.parent;

	dir$dmvbDisabledMasterField(p, g);
}

function dir$dmvbLoadMaVb(p){
	var maPl = p.valForm('ma_pl');
	var maNvb = p.valForm('ma_nvb');

	if(p.options.action == 'NEW') {
		if(maPl == '') {
			p.valForm('ma_vb', '', true);
			p.valForm('tu_so', 0, true);
			p.valForm('den_so', 0, true);

			p.jObject('ma_pl').focus(); 
			$.showToast(p.msg('RequireMaPl'));

			return;
		}
		if(maNvb == '') {
			p.valForm('ma_vb', '', true);
			p.jObject('ma_nvb').focus(); 
			$.showToast(p.msg('RequireMaNVB'));

			return;
		}

		p.request('LoadMavb', '', ['ma_pl','ma_nvb', 'ngay_ct']);
	}
}

dir$dmvb.prototype.formFieldValueChange = function(o, cF, v) {
    var p = this._dir;
	switch (cF){
		case 'ngay_ct':
			dir$dmvbLoadMaVb(p);
		break;
		case 'ma_pl':
			dir$dmvbLoadInfoMaPl(p)
			dir$dmvbLoadMaVb(p);
		break;
		case 'ma_nvb':
			dir$dmvbLoadMaVb(p);
		break;
		default:
		  break;
	}
};

function dir$dmvbDisabledMasterField(p){
	var maVb = p.valForm('ma_vb');
	if (maVb !== '') {
		p.setDisabled('ngay_ct', true);
		p.setDisabled('ma_nvb', true);
		p.setDisabled('ma_pl', true);
	}
	else {
		p.setDisabled('ngay_ct', false);
		p.setDisabled('ma_nvb', false);
		p.setDisabled('ma_pl', false);
	}
}
function dir$dmvbLoadInfoMaPl(p){
	var maPl = p.valForm('ma_pl');

	if (p.options.action == 'NEW') {
		p.request('LoadInfoMaPl', '', ['ma_pl']);
	}
	else {
		console.log('Không load dữ liệu');
	}
}






.modal-dialog-lg{min-width:960px!important;}
.control-label.tt {color: #499b98; text-decoration: underline}
.control-label.ma_pl, .control-label.ma_nvb, .control-label.ngay_ct {color: #499b98;}







IF @ma_pl <> '' BEGIN
	SELECT tu_so [!tu_so], den_so [!den_so] FROM dmplvb WHERE ma_pl = @ma_pl
END
ELSE BEGIN
	SELECT 0 [!tu_so], 0 [!den_so]
END






EXEC [dbo].[st_CreateDocumentCode] @ngay_ct, @ma_pl, @ma_nvb;






select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table

declare @script nvarchar(4000)
if @action in ('EDIT', 'VIEW') exec ISWIFTStoreGetListFiles 'xfile', @ma_vb, 'dmvb', '', @script output
if @script is null set @script = ''

select @script as script
drop table #@@table






update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]
update dmttin set status = 0 from dmttin where id0 = rtrim(@ma_vb) and xgroup = 'dmvb'
if @xfile <> '' update dmttin set status = 1, id0 = @ma_vb from dmttin where charindex(id, @xfile) > 0 and xgroup = 'dmvb'






if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, '@@firstFieldKey' as field
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit






if @xfile <> '' update dmttin set status = 1, id0 = @ma_vb from dmttin where charindex(id, @xfile) > 0 and xgroup = 'dmvb'







update #data set unit_id = @@unit
@@insert
